namespace {
inline int64_t CeilDiv(int64_t a, int64_t b) { return (a + b - 1) / b; }
}

namespace optiling {
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 输入 x: [N, Cin, Hin, Win], 权重 w: [Cin, Cout, K, K]
    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);
    if (x_shape == nullptr || w_shape == nullptr) {
        return ge::GRAPH_FAILED;
    }

    int64_t N   = x_shape->GetOriginShape().GetDim(0);
    int64_t Cin = x_shape->GetOriginShape().GetDim(1);
    int64_t Hin = x_shape->GetOriginShape().GetDim(2);
    int64_t Win = x_shape->GetOriginShape().GetDim(3);

    int64_t WinCin = w_shape->GetOriginShape().GetDim(0); // should equal Cin
    int64_t Cout   = w_shape->GetOriginShape().GetDim(1);
    int64_t K      = w_shape->GetOriginShape().GetDim(2); // square kernel
    (void)WinCin;

    int64_t stride = 1;
    int64_t padding = 0;
    int64_t dilation = 1;

    // 获取属性（若未设置则使用默认值）
    (void)context->GetAttr("stride", stride);
    (void)context->GetAttr("padding", padding);
    (void)context->GetAttr("dilation", dilation);

    int64_t Hout = (Hin - 1) * stride - 2 * padding + dilation * (K - 1) + 1;
    int64_t Wout = (Win - 1) * stride - 2 * padding + dilation * (K - 1) + 1;

    // 设置并行 block 数，沿 Cout 维度划分
    uint32_t maxBlock = 32;
    uint32_t usedBlock = static_cast<uint32_t>(std::min<int64_t>(Cout, maxBlock));
    context->SetBlockDim(usedBlock);

    uint32_t cPerCore = static_cast<uint32_t>(CeilDiv(Cout, static_cast<int64_t>(usedBlock)));

    ConvTransposed2dAsymmetricInputSquareKernelDilatedPaddedStridedCustomTilingData tiling;
    tiling.set_n(static_cast<uint32_t>(N));
    tiling.set_cin(static_cast<uint32_t>(Cin));
    tiling.set_cout(static_cast<uint32_t>(Cout));
    tiling.set_hin(static_cast<uint32_t>(Hin));
    tiling.set_win(static_cast<uint32_t>(Win));
    tiling.set_hout(static_cast<uint32_t>(Hout));
    tiling.set_wout(static_cast<uint32_t>(Wout));
    tiling.set_k(static_cast<uint32_t>(K));
    tiling.set_stride(static_cast<uint32_t>(stride));
    tiling.set_padding(static_cast<uint32_t>(padding));
    tiling.set_dilation(static_cast<uint32_t>(dilation));
    tiling.set_cPerCore(static_cast<uint32_t>(cPerCore));

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *workspace = context->GetWorkspaceSizes(1);
    workspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

