static inline int64_t deconv_out_size(int64_t in, int64_t kernel, int64_t stride, int64_t padding, int64_t dilation) {
    return (in - 1) * stride - 2 * padding + dilation * (kernel - 1) + 1;
}

at::Tensor conv_transposed_2d_asymmetric_input_square_kernel_dilated_padded_strided_custom_impl_npu(
    const at::Tensor& x, const at::Tensor& w, int64_t stride, int64_t padding, int64_t dilation) {
    // x: [N, Cin, Hin, Win], w: [Cin, Cout, K, K]
    TORCH_CHECK(x.dim() == 4, "x must be 4D");
    TORCH_CHECK(w.dim() == 4, "w must be 4D");
    auto N = x.size(0);
    auto Cin = x.size(1);
    auto Hin = x.size(2);
    auto Win = x.size(3);
    TORCH_CHECK(w.size(0) == Cin, "w.shape[0] must equal Cin");
    auto Cout = w.size(1);
    auto K = w.size(2);
    TORCH_CHECK(w.size(2) == w.size(3), "kernel must be square");

    auto Hout = deconv_out_size(Hin, K, stride, padding, dilation);
    auto Wout = deconv_out_size(Win, K, stride, padding, dilation);

    at::Tensor y = at::empty({N, Cout, Hout, Wout}, x.options());
    EXEC_NPU_CMD(aclnnConvTransposed2dAsymmetricInputSquareKernelDilatedPaddedStridedCustom, x, w, stride, padding, dilation, y);
    return y;
}

